@Composable
fun EmptyDocs() {
    DemoExample("Basic usage", "The default empty illustration and text.") {
        ElEmpty()
    }
    DemoExample("Custom description and action", "Provide a description and bottom content.") {
        ElEmpty(description = "No records found") {
            ElButton(onClick = {}, text = "Create", type = ElType.Primary, size = ElSize.Small)
        }
    }
    DemoExample("Image size", "Change the illustration size.") {
        ElEmpty(description = "Small empty state", imageSize = 80.dp)
    }

    DemoExample("Custom image", "Replace the default empty illustration.") {
        ElEmpty(
            description = "No projects",
            image = {
                Box(
                    Modifier.size(96.dp).background(LocalElTheme.current.colors.primary.copy(alpha = 0.15f), RoundedCornerShape(16.dp)),
                    contentAlignment = Alignment.Center,
                ) { BasicText("📁", style = LocalElTheme.current.typography.extraLarge) }
            },
        )
    }
    DemoExample("Bottom content", "Add an action below the empty description.") {
        ElEmpty(description = "No data") {
            ElButton(onClick = {}, text = "Create", type = ElType.Primary)
        }
    }
    DemoExample("Custom description content", "Replace the description text with rich content.") {
        val theme = LocalElTheme.current
        ElEmpty(
            descriptionContent = {
                Column(
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(4.dp),
                ) {
                    BasicText(
                        "No matching orders",
                        style = theme.typography.medium.copy(color = theme.colors.textPrimary),
                    )
                    BasicText(
                        "Try adjusting the filters or clearing the search.",
                        style = theme.typography.small.copy(color = theme.colors.textSecondary),
                    )
                }
            },
        ) {
            ElButton(onClick = {}, text = "Clear filters", size = ElSize.Small)
        }
    }
}
